syntax = "proto3";

package vector;

// A single vector record streamed by the client.
message VectorRecord {
  int64 id = 1;
  repeated float vector = 2;
  string metadata = 3;
}

// Summary returned after a client-streaming ingestion completes.
message IngestSummary {
  int64 received = 1;  // total records received during the RPC
  int64 written = 2;   // total rows written to LanceDB
  int64 batches = 3;   // number of batches flushed
}

// Request for a nearest-neighbor search.
message SearchRequest {
  repeated float query_vector = 1;
  int32 k = 2;
}

// A single search result entry.
message SearchHit {
  int64 id = 1;
  float distance = 2;
  string metadata = 3;
}

// Response containing ranked nearest neighbors (ascending distance).
message SearchResponse {
  repeated SearchHit hits = 1;
}

service VectorService {
  // Client-streaming ingestion: client streams many VectorRecord messages,
  // server buffers them into fixed-size batches and writes to LanceDB.
  rpc IngestVectors(stream VectorRecord) returns (IngestSummary);

  // Unary similarity search.
  rpc Search(SearchRequest) returns (SearchResponse);
}
